class Solution {
public:
    int mctFromLeafValues(vector<int>& arr) {
        vector<int> st = {INT_MAX};
        int cost = 0;
        for (int i = 0; i < (int)arr.size(); i++) {
            while (st.back() <= arr[i]) {
                int mid = st.back();
                st.pop_back();
                cost += mid * min(st.back(), arr[i]);
            }
            st.push_back(arr[i]);
        }
        while (st.size() > 2) {
            int mid = st.back();
            st.pop_back();
            cost += mid * st.back();
        }
        return cost;
    }
};
